{
  "issues": [],
  "questions": [],
  "storageAudit": {
    "format": "json",
    "evidenceLines": [57, 58, 60, 73, 86, 87],
    "rationale": "localStorage의 단일 parcel_data 키에 JSON 직렬화 문자열로 저장되며, 로드 및 쓰기 후보 모두에 대해 단일 JSON 구조 검증을 수행합니다.",
    "cases": [
      {
        "state": "absent",
        "action": "initialize",
        "verdict": "consistent",
        "evidenceLines": [73],
        "trigger": {
          "evidenceLines": [73]
        },
        "authorizationScopeIds": [],
        "rationale": "스토리지 getItem 결과가 null인 경우에만 최초 실행으로 처리하여 메모리 빈 목록을 초기화하고 사용자 첫 조작 전까지 스토리지 쓰기를 수행하지 않습니다."
      },
      {
        "state": "present_empty",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [75, 76],
        "trigger": {
          "evidenceLines": [75]
        },
        "authorizationScopeIds": [],
        "rationale": "빈 문자열이나 공백 문자열이 저장되어 있는 경우 원본을 덮어쓰거나 초기화하지 않고 보존하며 모든 변경을 차단합니다."
      },
      {
        "state": "invalid",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [46, 75, 76, 78],
        "trigger": {
          "evidenceLines": [75, 78]
        },
        "authorizationScopeIds": [],
        "rationale": "파싱 불가능한 JSON, 버전 불일치, 또는 공통 검증 규칙을 위반한 경우(예: received가 문자열인 경우) 원본을 보존하고 자동 초기화 없이 변경을 차단합니다."
      },
      {
        "state": "valid",
        "action": "load",
        "verdict": "consistent",
        "evidenceLines": [43, 94],
        "trigger": {
          "evidenceLines": [43, 58, 62, 63, 67, 68, 70, 73]
        },
        "authorizationScopeIds": [],
        "rationale": "JSON 파싱 및 공통 검증표의 모든 규칙을 통과한 유효 데이터에 한해 인메모리 복원 및 화면 표시를 진행합니다."
      },
      {
        "state": "read_error",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [45, 50],
        "trigger": {
          "evidenceLines": [45, 50]
        },
        "authorizationScopeIds": [],
        "rationale": "getItem 읽기 시 SecurityError 등 브라우저 접근 예외 발생 시 저장소 접근 불가 안내를 표시하고 빈 값 취급이나 신규 쓰기 없이 원본을 보존합니다."
      }
    ],
    "validation": {
      "rationale": "섹션 3.1 공통 검증표를 통해 로드 시점과 쓰기 직전 후보 상태 양쪽에 동일한 규칙을 엄격하게 적용하고 있습니다.",
      "rules": [
        {
          "rule": "schemaVersion은 정수 1이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 62]
          },
          "candidate": {
            "evidenceLines": [58, 62, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "버전 불일치 시 로드 차단 및 쓰기 후보 검증이 적용됩니다."
        },
        {
          "rule": "nextSeq는 양의 안전 정수이며 모든 items의 seq보다 커야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 63]
          },
          "candidate": {
            "evidenceLines": [58, 63, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "nextSeq의 타입, 범위 및 max(seq) 초과 불변식을 공통 검증합니다."
        },
        {
          "rule": "items는 배열이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 64]
          },
          "candidate": {
            "evidenceLines": [58, 64, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "items 루트 컬렉션이 배열 형태인지 검증합니다."
        },
        {
          "rule": "items[].id는 공백이 아닌 고유 문자열이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 65]
          },
          "candidate": {
            "evidenceLines": [58, 65, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "배열 내 항목 ID의 문자열 타입 및 고유성을 검증합니다."
        },
        {
          "rule": "items[].seq는 양의 안전 정수이며 배열 내 고유해야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 66]
          },
          "candidate": {
            "evidenceLines": [58, 66, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "항목 순번의 양의 정수 타입 및 중복 불가 불변식을 검증합니다."
        },
        {
          "rule": "items[].name은 앞뒤 공백 제외 1자 이상의 문자열이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 67]
          },
          "candidate": {
            "evidenceLines": [21, 58, 67, 85]
          },
          "acceptance": {
            "evidenceLines": [27, 79]
          },
          "rationale": "공백 전용 입력 또는 빈 이름에 대한 로드/후보 검증 및 거부 사례가 명시되어 있습니다."
        },
        {
          "rule": "items[].date는 실제 존재하는 YYYY-MM-DD 달력 날짜여야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 68]
          },
          "candidate": {
            "evidenceLines": [22, 58, 68, 85]
          },
          "acceptance": {
            "evidenceLines": [27, 75, 79]
          },
          "rationale": "2026-02-30, 2026-11-31 등 존재하지 않는 달력 날짜에 대한 차단 사례가 구체적으로 제시되어 있습니다."
        },
        {
          "rule": "items[].memo는 문자열 타입이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 69]
          },
          "candidate": {
            "evidenceLines": [23, 58, 69, 85]
          },
          "acceptance": {
            "evidenceLines": [75]
          },
          "rationale": "메모 필드의 문자열 타입 요건이 정의되어 있습니다."
        },
        {
          "rule": "items[].received는 기본형 불리언(true/false)이어야 함",
          "status": "supported",
          "load": {
            "evidenceLines": [11, 58, 70]
          },
          "candidate": {
            "evidenceLines": [58, 70, 85]
          },
          "acceptance": {
            "evidenceLines": [12, 75, 78]
          },
          "rationale": "문자열 '받음' 등 비불리언 값 저장 시 로드를 차단하고 원본을 보존하는 구체적 사례가 명시되어 있습니다."
        }
      ]
    }
  }
}

